-- The catalogue, so a fresh database is the real catalogue.
--
-- `supabase db reset` did not reproduce this project. Migrations run BEFORE
-- seed.sql, so migration 15 updated products that seed.sql had not inserted
-- yet and every price, description and spec it carries silently applied to
-- nothing. A reset produced 24 nameless POA rows, and the state anyone had
-- been developing against existed only because it had been built up
-- incrementally and had never been rebuilt from scratch.
--
-- The rows move here, above the seed, with their commercial data attached, so
-- the catalogue is inserted complete in one statement rather than inserted
-- bare and then repaired by an earlier migration.
--
-- Migration 15 is left exactly as it was. On any database where products
-- already existed it did its job, and rewriting an applied migration to fix a
-- later discovery is how two environments stop agreeing. It is superseded, not
-- corrected: THIS file is where a price or a description is edited now.
--
-- `on conflict (slug) do nothing` because the importer and migration 15 may
-- already have produced these rows. Nothing here overwrites a live edit.
--
-- Prices INCLUDE VAT, per D50.

insert into products (
  name, slug, category_id, price, price_display_mode, availability, unit,
  description, short_description, specs, face_type, is_published, source_path
)
select
  r.name, r.slug,
  (select id from categories where source_path = '12MM SINTERED STONES'),
  r.price,
  'fixed'::price_display_mode,
  'in_stock'::availability,
  'per slab',
  r.description, r.short_desc, r.specs::jsonb, r.face::face_type,
  true, r.source
from (values
  ('Amber Jade', 'amber-jade', 65000, 'Warm taupe, greige and amber tones run in soft vertical layers across the surface, creating the calm, natural look of onyx. A sophisticated choice for spaces that call for warmth, texture and understated luxury.', 'Warm taupe, greige and amber tones run in soft vertical layers across the surface, creating the calm, natural look of onyx.', '{"Slab size": "3200 x 1600 x 12mm", "Thickness": "12mm", "Finish": "Polished", "Body composition": "Super White Body", "Recommended for": "Kitchen countertops, islands, vanity tops, feature walls and reception areas"}', 'one_face', '12MM SINTERED STONES/AMBER JADE'),
  ('Beverly Gold', 'beverly-gold', 65000, 'A soft off-white background is crossed by delicate grey and warm ochre veins. Light and elegant, Beverly Gold creates a bright, welcoming feel while adding just the right amount of movement to a luxury interior.', 'A soft off-white background is crossed by delicate grey and warm ochre veins.', '{"Slab size": "3200 x 1600 x 12mm", "Thickness": "12mm", "Finish": "Polished", "Body composition": "Super White Full Body", "Recommended for": "Kitchen countertops, islands, vanity tops, feature walls and reception areas"}', 'book_match', '12MM SINTERED STONES/BEVERLY GOLD'),
  ('Bianco Fendi', 'bianco-fendi', 70000, 'Clean white meets striking grey patterns that move boldly across the surface. Bianco Fendi has a strong architectural character, making it ideal for modern kitchens, statement islands, reception desks and feature walls.', 'Clean white meets striking grey patterns that move boldly across the surface.', '{"Slab size": "3200 x 1600 x 12mm", "Thickness": "12mm", "Finish": "Silky", "Body composition": "Super White Full Body", "Recommended for": "Kitchen countertops, islands, vanity tops, feature walls and reception areas"}', 'book_match', '12MM SINTERED STONES/BIANCO FENDI'),
  ('Bvlgari', 'bvlgari', 95000, 'Inspired by the dramatic beauty of Calacatta Viola, Bvlgari combines a brilliant white background with rich burgundy and deep plum movement. Bold, luxurious and fashion-forward, it is designed for interiors that are meant to make a statement.', 'Inspired by the dramatic beauty of Calacatta Viola, Bvlgari combines a brilliant white background with rich burgundy and deep plum movement.', '{"Slab size": "3200 x 1600 x 12mm", "Thickness": "12mm", "Finish": "Polished", "Body composition": "Translucent Full Body", "Recommended for": "Kitchen countertops, islands, vanity tops, feature walls and reception areas"}', 'one_face', '12MM SINTERED STONES/BVLGARI'),
  ('Calcatta Gold', 'calcatta-gold', 60000, 'Elegant grey and warm gold veins sweep diagonally across a brilliant white background. Calcatta Gold offers the timeless beauty of classic marble with a refined, contemporary feel.', 'Elegant grey and warm gold veins sweep diagonally across a brilliant white background.', '{"Slab size": "3200 x 1600 x 12mm", "Thickness": "12mm", "Finish": "Polished", "Body composition": "Super White Body", "Recommended for": "Kitchen countertops, islands, vanity tops, feature walls and reception areas"}', 'book_match', '12MM SINTERED STONES/CALCATTA GOLD'),
  ('Calcatta Oro', 'calcatta-oro', 65000, 'A bright white base with bold charcoal-grey and warm gold veins that flow organically across the surface. Dramatic yet elegant, Calcatta Oro brings the look of luxurious Italian marble into sophisticated kitchens, bathrooms and feature spaces.', 'A bright white base with bold charcoal-grey and warm gold veins that flow organically across the surface.', '{"Slab size": "3200 x 1600 x 12mm", "Thickness": "12mm", "Finish": "Silky", "Body composition": "Super White Body", "Recommended for": "Kitchen countertops, islands, vanity tops, feature walls and reception areas"}', 'book_match', '12MM SINTERED STONES/CALCATTA ORO'),
  ('Cyprus Light Grey', 'cyprus-light-grey', 75000, 'A cool grey background with subtle speckling and natural-looking texture gives Cyprus Light Grey the character of limestone and concrete. Its understated finish works beautifully in contemporary, industrial and minimalist spaces.', 'A cool grey background with subtle speckling and natural-looking texture gives Cyprus Light Grey the character of limestone and concrete.', '{"Slab size": "3200 x 1600 x 12mm", "Thickness": "12mm", "Finish": "3D Digital", "Body composition": "Light Grey Speckled Body", "Recommended for": "Kitchen countertops, islands, vanity tops, feature walls and reception areas"}', 'one_face', '12MM SINTERED STONES/CYPRUS LIGHT GREY'),
  ('Etereo', 'etereo', 65000, 'Soft warm-grey tones blend gently across a clean surface, creating a calm and seamless look. Etereo is perfect for modern interiors where simplicity, warmth and quiet luxury take centre stage.', 'Soft warm-grey tones blend gently across a clean surface, creating a calm and seamless look.', '{"Slab size": "3200 x 1600 x 12mm", "Thickness": "12mm", "Finish": "Matte", "Body composition": "Light Grey Body", "Recommended for": "Kitchen countertops, islands, vanity tops, feature walls and reception areas"}', 'one_face', '12MM SINTERED STONES/ETEREO'),
  ('Galaxy Bianco', 'galaxy-bianco', 65000, 'Soft layers of cream, alabaster and grey flow gently across the surface, inspired by the natural beauty of quartzite and marble. Galaxy Bianco brings light, movement and a sense of calm to refined interiors.', 'Soft layers of cream, alabaster and grey flow gently across the surface, inspired by the natural beauty of quartzite and marble.', '{"Slab size": "3200 x 1600 x 12mm", "Thickness": "12mm", "Finish": "Bush Hammered", "Body composition": "Super White Body", "Recommended for": "Kitchen countertops, islands, vanity tops, feature walls and reception areas"}', 'one_face', '12MM SINTERED STONES/GALAXY BIANCO'),
  ('Jatoba Brown', 'jatoba-brown', 85000, 'Deep earthy brown, charcoal and bronze tones are brought to life with delicate white veins. Rich and dramatic, Jatoba Brown adds depth and warmth to sophisticated interiors and is particularly striking in darker, moodier spaces.', 'Deep earthy brown, charcoal and bronze tones are brought to life with delicate white veins.', '{"Slab size": "3200 x 1600 x 12mm", "Thickness": "12mm", "Finish": "3D Digital", "Body composition": "Brown Body", "Recommended for": "Kitchen countertops, islands, vanity tops, feature walls and reception areas"}', 'one_face', '12MM SINTERED STONES/JATOBA BROWN'),
  ('Limestone Beige', 'limestone-beige', 70000, 'A warm sandy-beige background is finished with fine natural-looking speckles. Soft and inviting, Limestone Beige brings the relaxed beauty of natural coastal stone into warm, elegant interiors.', 'A warm sandy-beige background is finished with fine natural-looking speckles.', '{"Slab size": "3200 x 1600 x 12mm", "Thickness": "12mm", "Finish": "Soft Matte", "Body composition": "Beige Body", "Recommended for": "Kitchen countertops, islands, vanity tops, feature walls and reception areas"}', 'one_face', '12MM SINTERED STONES/LIMESTONE BEIGE'),
  ('Limestone Creamy', 'limestone-creamy', 65000, 'Warm cream tones are paired with subtle fossil-like detailing and natural variation. Limestone Creamy creates a timeless, Mediterranean feel that works beautifully across kitchens, bathrooms, walls and other refined spaces.', 'Warm cream tones are paired with subtle fossil-like detailing and natural variation.', '{"Slab size": "3200 x 1600 x 12mm", "Thickness": "12mm", "Finish": "Bush Hammered", "Body composition": "Super White Body", "Recommended for": "Kitchen countertops, islands, vanity tops, feature walls and reception areas"}', 'one_face', '12MM SINTERED STONES/LIMESTONE CREAMY'),
